"""
Execution-grounded verification of agent-authored workspaces.

This module implements the ExecutionHarness which verifies code by actually
running it (parsing, installing, importing, testing) rather than relying on
textual analysis or file counts.
"""

import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import re
import json
import importlib.util
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module if available, otherwise define minimal fallbacks
# to ensure this module can be imported even if artifacts.py is not yet present
# or in a different location. However, the spec implies artifacts.py is a dependency.
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        filter_bundle,
        partition_bundle,
        count_source_files,
        EXCLUDED_DIR_SEGMENTS,
        EXCLUDED_DIR_SUFFIXES
    )
except ImportError:
    # Fallback definitions if artifacts.py is not importable in this context
    # These mirror the spec for artifacts.py to allow harness.py to function
    # in isolation for testing or if the dependency is resolved differently.

    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if '*' in path or '`' in path:
            return True
        if path != path.strip():
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        # Strip markdown decoration
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle.keys():
            if any(path.endswith(s) for s in suffixes):
                count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"[{status_icon}] {g.name}: {g.status} ({g.method})")
            if g.detail:
                lines.append(f"    Detail: {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional filename hint
    # Common patterns:
    # ```python
    # path/to/file.py
    # ... code ...
    # ```
    # Or sometimes the filename is in the fence info string: ```python path/to/file.py

    blocks = {}
    # Match ```lang filename\ncontent\n``` or ```lang\ncontent\n```
    # We look for ``` followed by optional lang, optional filename, newline, content, ```

    pattern = r'```(?:\s*(\w+))?(?:\s+([^\n`]+))?\n(.*?)\n```'
    matches = re.finditer(pattern, text, re.DOTALL)

    for match in matches:
        lang = match.group(1)
        filename_hint = match.group(2)
        content = match.group(3)

        # Determine path
        path = None
        if filename_hint:
            # Clean up filename hint
            path = filename_hint.strip()
            # Remove quotes if present
            if path.startswith('"') and path.endswith('"'):
                path = path[1:-1]
            elif path.startswith("'") and path.endswith("'"):
                path = path[1:-1]

        # If no filename hint, try to find a path in the first line of content
        if not path:
            lines = content.split('\n')
            if lines:
                first_line = lines[0].strip()
                # Heuristic: if it looks like a path (contains / or .py etc)
                if '/' in first_line or first_line.endswith('.py'):
                    path = first_line
                    # Remove the path line from content if it was just a path declaration
                    # But often the path is a comment or just the first line.
                    # If the first line is just the path, we might want to strip it.
                    # However, standard markdown code blocks don't usually have the path inside.
                    # Let's assume if it's not a valid python statement, it might be a path.
                    # For simplicity, if we found a path in the hint, we use it.
                    # If we found a path in the first line, we use it but keep content as is?
                    # Usually, agents write:
                    # ```python
                    # # path/to/file.py
                    # ...
                    # ```
                    # Or just the code.
                    # If we can't determine a path, we skip or use a dummy?
                    # The spec says "path->content map". If no path, we can't map it.
                    pass

        if path:
            # Sanitize path
            path = sanitize_path(path)
            if path:
                blocks[path] = content

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method or attribute to get files
            # Common patterns: workspace.files, workspace.get_bundle(), workspace.list_files()
            if hasattr(workspace, 'get_bundle'):
                bundle = workspace.get_bundle()
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'
            elif hasattr(workspace, 'list_files'):
                # list_files might return paths, need to read them
                # This depends on the specific workspace implementation
                # For now, if it's a dict-like, use it
                if isinstance(workspace, dict):
                    bundle = workspace
                    source = 'workspace'
                else:
                    # Try to iterate if it's a list of paths
                    try:
                        files = workspace.list_files()
                        if isinstance(files, dict):
                            bundle = files
                            source = 'workspace'
                        elif isinstance(files, list):
                            # Assume we can read them? No, we need content.
                            # If workspace doesn't provide content, we can't verify.
                            pass
                    except Exception:
                        pass
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'

        # If bundle is empty, try extracting from deliverable text
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='packaging', detail='No packaging metadata found'),
            GateResult(name='smoke', status=FAILED, method='import', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No tests found'),
            GateResult(name='telemetry', status=FAILED, method='ast.analysis', detail='No telemetry code found'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=len(gates) * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to get authored files
        authored_bundle = filter_bundle(bundle)

        # Count files
        python_files = count_source_files(authored_bundle, suffixes=('.py',))
        authored_files = len(authored_bundle)

        if python_files == 0:
            # No python files to verify
            return self._empty_report(source)

        # Create temp directory
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            # Run gates
            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out generated dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    full_path = os.path.join(root, file)
                    rel_path = os.path.relpath(full_path, workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        python_files = count_source_files(authored, suffixes=('.py',))
        authored_files = len(authored)

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        method = 'ast.parse'
        py_files = [p for p in authored.keys() if p.endswith('.py')]

        if not py_files:
            return GateResult(name='syntax', status=FAILED, method=method, detail='No Python files found', duration_s=time.time()-start)

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(name='syntax', status=FAILED, method=method, detail='; '.join(errors), duration_s=duration)

        return GateResult(name='syntax', status=PASSED, method=method, detail=f'{len(py_files)} files parsed successfully', duration_s=duration)

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        method = 'packaging'

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(name='build', status=FAILED, method=method, detail='No packaging metadata found', duration_s=time.time()-start)

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                import tomllib
            except ImportError:
                try:
                    import toml as tomllib
                except ImportError:
                    return GateResult(name='build', status=SKIPPED, method=method, detail='tomllib/toml not available', duration_s=time.time()-start)

            try:
                content = authored['pyproject.toml']
                data = tomllib.loads(content)
                # Check for required tables
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(name='build', status=FAILED, method=method, detail='pyproject.toml missing required tables', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method=method, detail=f'Invalid pyproject.toml: {e}', duration_s=time.time()-start)

        # Try pip install
        # Check if pip is available
        try:
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], capture_output=True, timeout=10)
        except Exception:
            return GateResult(name='build', status=SKIPPED, method=method, detail='pip not available', duration_s=time.time()-start)

        # Run pip install -e .
        try:
            # We need to run in the workdir
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(name='build', status=PASSED, method=method, detail='pip install successful', duration_s=duration)
            else:
                return GateResult(name='build', status=FAILED, method=method, detail=f'pip install failed: {result.stderr}', duration_s=duration)
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method=method, detail='pip install timed out', duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name='build', status=FAILED, method=method, detail=f'pip install error: {e}', duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        method = 'import'

        # Find non-test modules
        # Exclude test files
        modules = []
        for path in authored.keys():
            if not path.endswith('.py'):
                continue
            if 'test' in os.path.basename(path).lower():
                continue
            # Convert path to module name
            # e.g. src/foo/bar.py -> foo.bar (if src is on path)
            # We will add workdir and workdir/src to PYTHONPATH
            modules.append(path)

        if not modules:
            return GateResult(name='smoke', status=FAILED, method=method, detail='No importable modules found', duration_s=time.time()-start)

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = os.pathsep.join([workdir, src_dir])
        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Try importing each module
        import_errors = []
        module_not_found_errors = []

        for path in modules:
            # Determine module name
            # If path is src/foo/bar.py, and src is on path, module is foo.bar
            # If path is foo/bar.py, and workdir is on path, module is foo.bar

            rel_path = path
            if rel_path.startswith('src/'):
                module_name = rel_path[4:-3].replace('/', '.')
            else:
                module_name = rel_path[:-3].replace('/', '.')

            # Run subprocess to import
            code = f"import {module_name}"
            try:
                result = subprocess.run(
                    [self.python_executable, '-c', code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped.
                        # This is tricky. If `import foo` fails with ModuleNotFoundError: foo, it's a failure.
                        # If `import foo` fails with ModuleNotFoundError: bar (where bar is imported by foo), it's skipped.
                        # We can't easily distinguish without parsing the error.
                        # Heuristic: If the error mentions the module name we tried to import, it's a failure.
                        if module_name in stderr or module_name.split('.')[0] in stderr:
                            import_errors.append(f"{module_name}: {stderr.strip()}")
                        else:
                            module_not_found_errors.append(f"{module_name}: {stderr.strip()}")
                    else:
                        import_errors.append(f"{module_name}: {stderr.strip()}")
            except Exception as e:
                import_errors.append(f"{module_name}: {e}")

        duration = time.time() - start

        if import_errors:
            return GateResult(name='smoke', status=FAILED, method=method, detail='; '.join(import_errors), duration_s=duration)

        if module_not_found_errors:
            return GateResult(name='smoke', status=SKIPPED, method=method, detail='Third-party dependencies missing', duration_s=duration)

        return GateResult(name='smoke', status=PASSED, method=method, detail=f'{len(modules)} modules imported successfully', duration_s=duration)

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        method = 'pytest'

        # Find test files
        test_files = [p for p in authored.keys() if 'test' in os.path.basename(p).lower() and p.endswith('.py')]

        if not test_files:
            return GateResult(name='tests', status=FAILED, method=method, detail='No test files found', duration_s=time.time()-start)

        # Check if pytest is installed
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], capture_output=True, timeout=10)
            has_pytest = True
        except Exception:
            has_pytest = False

        src_dir = os.path.join(workdir, 'src')
        python_path = os.pathsep.join([workdir, src_dir])
        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        if has_pytest:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v', '--tb=short'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start
                if result.returncode == 0:
                    return GateResult(name='tests', status=PASSED, method=method, detail='All tests passed', duration_s=duration)
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        # Heuristic: if the error is about a third-party package, skip
                        # If it's about the project itself, fail
                        # This is hard to determine perfectly.
                        # If pytest collected 0 tests due to import errors, it might be skipped.
                        if 'collected 0 items' in result.stdout or 'collected 0 items' in result.stderr:
                             return GateResult(name='tests', status=SKIPPED, method=method, detail='Tests skipped due to missing dependencies', duration_s=duration)
                    return GateResult(name='tests', status=FAILED, method=method, detail='Tests failed', duration_s=duration)
            except subprocess.TimeoutExpired:
                return GateResult(name='tests', status=FAILED, method=method, detail='Tests timed out', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='tests', status=FAILED, method=method, detail=f'Pytest error: {e}', duration_s=time.time()-start)
        else:
            # Stdlib fallback
            method = 'unittest_fallback'
            # Run a script that imports test files and runs tests
            # This is complex to do in a single subprocess call robustly.
            # We'll write a temporary runner script.

            runner_code = """
import sys
import os
import unittest
import importlib.util
import inspect

def run_tests():
    # Ensure workdir and src are on sys.path for local imports
    cwd = os.getcwd()
    src_dir = os.path.join(cwd, 'src')
    if cwd not in sys.path:
        sys.path.insert(0, cwd)
    if os.path.isdir(src_dir) and src_dir not in sys.path:
        sys.path.insert(0, src_dir)

    test_files = sys.argv[1:]
    suite = unittest.TestSuite()
    errors = []

    for file in test_files:
        try:
            # Add to path
            dir_name = os.path.dirname(file)
            if dir_name not in sys.path:
                sys.path.insert(0, dir_name)

            # Load module
            spec = importlib.util.spec_from_file_location(
                'test_module', file
            )
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)

            # Collect tests
            # 1. unittest.TestCase subclasses
            for name in dir(module):
                obj = getattr(module, name)
                if isinstance(obj, type) and issubclass(obj, unittest.TestCase) and obj.__module__ == module.__name__:
                    suite.addTests(unittest.defaultTestLoader.loadTestsFromTestCase(obj))

