    def _gate_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()
        method = 'ast.analysis'

        py_files = [p for p in authored.keys() if p.endswith('.py')]

        if not py_files:
            return GateResult(name='telemetry', status=FAILED, method=method, detail='No Python files found', duration_s=time.time()-start)

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span',
            'start_span',
            'get_tracer',
            'get_tracer_provider',
            'set_tracer_provider',
            'get_meter'
        }

        for path in py_files:
            content = authored[path]
            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls
                if isinstance(node, ast.Call):
                    func = node.func
                    # Direct call: start_span()
                    if isinstance(func, ast.Name) and func.id in tracer_methods:
                        has_call = True
                    # Attribute call: tracer.start_span()
                    elif isinstance(func, ast.Attribute) and func.attr in tracer_methods:
                        has_call = True

            if has_import and has_call:
                break

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(name='telemetry', status=PASSED, method=method, detail='OpenTelemetry imports and calls found', duration_s=duration)
        elif has_import:
            return GateResult(name='telemetry', status=FAILED, method=method, detail='OpenTelemetry imported but no tracer/span calls found', duration_s=duration)
        else:
            return GateResult(name='telemetry', status=FAILED, method=method, detail='No OpenTelemetry usage found', duration_s=duration)
